css:
/* Липкая кнопка заявки на телефоне. Цвета — токены дизайн-системы, запасные значения на случай их отсутствия.
   --scta-offset: высота нижнего меню или панели cookie, если они тоже прижаты к низу экрана. */
.scta-spacer { display: none; }
.scta { display: none; }
@media (max-width: 767.98px) {
  /* Место в конце страницы, чтобы кнопка не закрыла последние строки подвала. Постоянное: ничего не прыгает */
  .scta-spacer { display: block; height: calc(76px + var(--scta-offset, 0px) + env(safe-area-inset-bottom, 0px)); }
  .scta {
    display: block;
    position: fixed;
    left: 0;
    right: 0;
    bottom: var(--scta-offset, 0px);
    z-index: 40; /* ниже модальных окон и баннера cookie, выше контента */
    box-sizing: border-box;
    padding: 12px 16px calc(12px + env(safe-area-inset-bottom, 0px));
    background: var(--color-surface, #ffffff);
    border-top: 1px solid var(--color-border, #e2e8f0);
    box-shadow: 0 -10px 24px -14px rgba(15, 23, 42, .35);
    /* Скрыто: под нижним краем, прозрачно, не ловит касания и фокус */
    transform: translate3d(0, calc(100% + var(--scta-offset, 0px)), 0);
    opacity: 0;
    visibility: hidden;
    /* Уход: 200ms (≈ 2/3 входа), разгон к краю — MD3 Accelerate. visibility выключается после ухода */
    transition: transform 200ms cubic-bezier(.3, 0, 1, 1), opacity 200ms cubic-bezier(.3, 0, 1, 1), visibility 0s linear 200ms;
  }
  .scta.is-shown {
    transform: translate3d(0, 0, 0);
    opacity: 1;
    visibility: visible;
    /* Вход: 300ms, торможение у места — MD3 Emphasized Decelerate. visibility включается сразу */
    transition: transform 300ms cubic-bezier(.05, .7, .1, 1), opacity 200ms cubic-bezier(.2, 0, 0, 1), visibility 0s;
  }
}
.scta__row { display: flex; gap: 8px; }
.scta__btn, .scta__alt {
  box-sizing: border-box;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 48px;
  border: 2px solid transparent; /* в контрастной теме Windows станет видимой рамкой */
  border-radius: var(--radius-pill, 999px);
  font: inherit;
  font-size: 16px;
  font-weight: 600;
  line-height: 1.2;
  text-decoration: none;
  -webkit-tap-highlight-color: transparent;
  touch-action: manipulation;
  transition: transform 120ms cubic-bezier(.2, 0, 0, 1);
}
.scta__btn {
  flex: 1 1 auto;
  min-width: 0;
  padding: 12px 20px;
  background: var(--color-primary, #1d4ed8);
  color: var(--color-on-primary, #ffffff);
  text-align: center;
}
.scta__alt {
  flex: 0 0 48px;
  width: 48px;
  background: transparent;
  border-color: var(--color-border, #cbd5e1);
  color: var(--color-text, #0f172a);
}
.scta__btn:active, .scta__alt:active { transform: scale(.97); }
.scta__btn:focus-visible, .scta__alt:focus-visible {
  outline: 3px solid var(--color-text, #0f172a);
  outline-offset: 3px;
}
/* Уровень 2 схемы iart («смягчить»): выезд снизу заменяем коротким проявлением на месте, нажатие — затемнением */
@media (prefers-reduced-motion: reduce) {
  .scta, .scta.is-shown { transform: none; }
  .scta { transition: opacity 150ms linear, visibility 0s linear 150ms; }
  .scta.is-shown { transition: opacity 150ms linear, visibility 0s; }
  .scta__btn, .scta__alt { transition: opacity 100ms linear; }
  .scta__btn:active, .scta__alt:active { transform: none; opacity: .85; }
}
@media (forced-colors: active) {
  .scta { border-top-color: CanvasText; }
  .scta__btn, .scta__alt { border-color: ButtonText; }
}
@media print {
  .scta, .scta-spacer { display: none; }
}

