// Липкая кнопка заявки: показать, когда главная кнопка первого экрана ушла вверх;
// спрятать, пока на экране форма, пока человек печатает, и насовсем — после отправки.
(() => {
  const bar = document.querySelector('.scta');
  if (!bar || !('IntersectionObserver' in window)) return; // без IO кнопка не появится: первый экран и форма работают и так
  const shown = el => !!el && el.getClientRects().length > 0; // display: none на телефоне — не годится в ориентир
  const after = [bar.dataset.after && document.querySelector(bar.dataset.after), document.querySelector('section')].find(shown);
  let forms = document.querySelectorAll(bar.dataset.hideOn || '#lead');
  if (!forms.length) forms = document.querySelectorAll('form');
  if (!after) return;
  // Только поля, которые открывают клавиатуру. Флажок, переключатель и список её не открывают, но держат фокус
  // после касания — с ними в списке панель пропадала до следующего касания мимо (квиз, калькулятор).
  const TEXT = 'textarea, input:not([type]), input[type=text], input[type=email], input[type=tel], input[type=number], input[type=search], input[type=url], input[type=password]';
  const typing = () => { const a = document.activeElement; return !!a && !bar.contains(a) && (a.isContentEditable || a.matches(TEXT)); };
  const seen = new Set(); // формы, которые сейчас на экране
  let passed = false, done = false, queued = false;
  const apply = () => { queued = false; bar.classList.toggle('is-shown', passed && !seen.size && !done && !typing()); };
  const schedule = () => { if (!queued) { queued = true; requestAnimationFrame(apply); } }; // одно решение за кадр
  const heroIO = new IntersectionObserver(entries => {
    const e = entries[entries.length - 1]; // за кадр может прийти несколько записей — важна последняя
    passed = !e.isIntersecting && e.boundingClientRect.top < 0; // ушла ВВЕРХ, а не ещё не доехали
    schedule();
  });
  const formIO = new IntersectionObserver(entries => {
    entries.forEach(e => (e.isIntersecting ? seen.add(e.target) : seen.delete(e.target)));
    schedule();
  });
  const stop = () => { // заявка ушла: второй раз не зовём и больше ничего не слушаем
    done = true; heroIO.disconnect(); formIO.disconnect();
    document.removeEventListener('focusin', schedule); document.removeEventListener('focusout', schedule);
    schedule();
  };
  heroIO.observe(after);
  forms.forEach(f => { formIO.observe(f); f.addEventListener('submit', stop, { once: true }); });
  document.addEventListener('focusin', schedule); // решение на следующем кадре: фокус успеет перейти
  document.addEventListener('focusout', schedule);
  bar.addEventListener('touchstart', () => {}, { passive: true }); // Safari на iPhone включает :active только при слушателе касаний
})();

