// Только если GSAP уже есть на странице: ставить из npm (npm i gsap), не с CDN. Анимацию по-прежнему делает CSS рецепта —
// GSAP здесь лишь решает «показать или спрятать». Файл js рецепта при этом не подключать.
import { gsap } from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger';
gsap.registerPlugin(ScrollTrigger);
const bar = document.querySelector('.scta');
const hero = bar && document.querySelector(bar.dataset.after || '#hero-cta');
const lead = bar && document.querySelector(bar.dataset.hideOn || '#lead');
if (hero && lead) { // нет панели, кнопки или формы — ничего не делаем и не падаем
  const TEXT = 'textarea, input:not([type]), input[type=text], input[type=email], input[type=tel], input[type=number], input[type=search], input[type=url], input[type=password]';
  let passed = false, atForm = false, done = false;
  const typing = () => { const a = document.activeElement; return !!a && !bar.contains(a) && (a.isContentEditable || a.matches(TEXT)); };
  const apply = () => bar.classList.toggle('is-shown', passed && !atForm && !done && !typing());
  const onFocus = () => requestAnimationFrame(apply);
  const triggers = [
    ScrollTrigger.create({ // низ главной кнопки ушёл за верх экрана
      trigger: hero, start: 'bottom top',
      onEnter: () => { passed = true; apply(); }, onLeaveBack: () => { passed = false; apply(); }
    }),
    ScrollTrigger.create({ // форма хотя бы краем на экране
      trigger: lead, start: 'top bottom', end: 'bottom top',
      onToggle: self => { atForm = self.isActive; apply(); }
    })
  ];
  lead.addEventListener('submit', () => { // заявка ушла: прячем насовсем и снимаем слежку
    done = true; apply(); triggers.forEach(t => t.kill());
    ['focusin', 'focusout'].forEach(t => document.removeEventListener(t, onFocus));
  }, { once: true });
  ['focusin', 'focusout'].forEach(t => document.addEventListener(t, onFocus));
}
